// NetVault's source-of-truth UI translation catalog is i18n-catalog.tsv.
// This script is generated by scripts/build_i18n.py. Do not edit i18n.js by hand.
(() => {
  "use strict";
  /* @CATALOG@ */

  const STORAGE_KEY = "netvault:language:v1";
  const COOKIE_KEY = "netvault_locale";
  const LANGUAGES = Object.freeze(["en", "zh-CN", "zh-TW"]);
  const ATTRIBUTES = Object.freeze(["aria-label", "title", "placeholder", "data-tooltip"]);
  const NUMBER = "([\\d,]+)";
  const DYNAMIC_RULES = [
    [new RegExp("^" + NUMBER + " files selected$"), ["已选择 $1 个文件", "已選取 $1 個檔案"]],
    [new RegExp("^" + NUMBER + " selected$"), ["已选择 $1 项", "已選取 $1 項"]],
    [new RegExp("^" + NUMBER + " journals$"), ["$1 种期刊", "$1 種期刊"]],
    [new RegExp("^" + NUMBER + " DOIs$"), ["$1 个 DOI", "$1 個 DOI"]],
    [new RegExp("^" + NUMBER + " results?$"), ["$1 条结果", "$1 筆結果"]],
    [/^Page (\d+) of (\d+)$/, ["第 $1 / $2 页", "第 $1 / $2 頁"]],
    [/^Showing (\d+)–(\d+) of (\d+) journals$/, ["显示 $1–$2 / 共 $3 种期刊", "顯示 $1–$2 / 共 $3 種期刊"]],
    [/^Uploading (\d+) PDFs?\.\.\.$/, ["正在上传 $1 个 PDF…", "正在上傳 $1 個 PDF…"]],
    [/^Uploading (\d+)%$/, ["上传中：$1%", "上傳中：$1%"]],
    [/^Hashing (\d+)\/(\d+) PDFs$/, ["正在计算 PDF 哈希：$1/$2", "正在計算 PDF 雜湊：$1/$2"]],
    [/^Saved (\d+) journals?$/, ["已保存 $1 种期刊", "已儲存 $1 種期刊"]],
    [/^Enter 1–(\d+)$/, ["请输入 1–$1", "請輸入 1–$1"]],
    [/^Signed in as (.+)$/, ["当前账号：$1", "目前帳號：$1"]],
    [/^Page (\d+)$/, ["第 $1 页", "第 $1 頁"]],
  ];
  const originals = new WeakMap();
  const attributes = new WeakMap();
  const pending = new Set();
  let frameScheduled = false;
  let titleSource = "";
  let titleLast = "";
  let observer = null;

  function normalizedLanguage(code) {
    if (!code || typeof code !== "string") return null;
    const raw = code.replace(/_/g, "-").toLowerCase();
    if (raw === "en" || raw.startsWith("en-")) return "en";
    if (raw === "zh-tw" || raw === "zh-hk" || raw === "zh-mo" || raw === "zh-hant"
        || raw.startsWith("zh-hant-")) return "zh-TW";
    if (raw === "zh" || raw === "zh-cn" || raw === "zh-sg" || raw === "zh-hans"
        || raw.startsWith("zh-hans-")) return "zh-CN";
    return null;
  }

  function chooseLanguage() {
    let saved = null;
    try { saved = localStorage.getItem(STORAGE_KEY); } catch { /* private mode */ }
    if (saved) {
      const choice = normalizedLanguage(saved);
      if (choice) return choice;
    }
    const cookie = document.cookie.match(/(?:^|;\s*)netvault_locale=([^;]+)/);
    if (cookie) {
      try {
        const choice = normalizedLanguage(decodeURIComponent(cookie[1]));
        if (choice) return choice;
      } catch { /* malformed legacy cookie */ }
    }
    for (const value of (navigator.languages || [navigator.language || "en"])) {
      const choice = normalizedLanguage(value);
      if (choice) return choice;
    }
    return "en";
  }

  const language = chooseLanguage();
  document.documentElement.lang = language;
  document.documentElement.dataset.language = language;

  function translateString(input) {
    if (language === "en" || typeof input !== "string") return input;
    const result = /^(\s*)([\s\S]*?)(\s*)$/.exec(input);
    if (!result) return input;
    const [, prefix, raw, suffix] = result;
    const key = raw.trim();
    if (!key) return input;
    const pair = CATALOG.get(key);
    if (pair) return prefix + pair[language === "zh-CN" ? 0 : 1] + suffix;
    for (const [pattern, variants] of DYNAMIC_RULES) {
      if (pattern.test(key)) {
        const translated = variants[language === "zh-CN" ? 0 : 1];
        return prefix + key.replace(pattern, translated) + suffix;
      }
    }
    return input;
  }

  function excluded(node) {
    const parent = node.nodeType === 1 ? node : node.parentElement;
    if (!parent || !parent.closest) return false;
    return Boolean(parent.closest(
      "script,style,code,pre,kbd,samp,textarea,svg,[contenteditable],"
      + "[data-i18n-ignore],.paper-title,.paper-authors,.paper-metadata,"
      + ".doi-link,.paper-file-meta,.pdf-meta-fields,.heat-journal,"
      + ".journal-list-journals,.syntax-url,.syntax-path"
    ));
  }

  function translateTextNode(node) {
    if (!node || node.nodeType !== 3 || excluded(node)) return;
    const current = node.nodeValue;
    let saved = originals.get(node);
    if (!saved || saved.last !== current) saved = {source: current, last: current};
    const next = translateString(saved.source);
    saved.last = next;
    originals.set(node, saved);
    if (next !== current) node.nodeValue = next;
  }

  function translateAttributes(element) {
    if (!element || element.nodeType !== 1 || excluded(element)) return;
    let saved = attributes.get(element);
    if (!saved) saved = {};
    for (const name of ATTRIBUTES) {
      if (!element.hasAttribute(name)) continue;
      const current = element.getAttribute(name);
      let entry = saved[name];
      if (!entry || entry.last !== current) entry = {source: current, last: current};
      const next = translateString(entry.source);
      entry.last = next;
      saved[name] = entry;
      if (current !== next) element.setAttribute(name, next);
    }
    attributes.set(element, saved);
  }

  function translate(root = document.body) {
    if (!root || language === "en") return;
    if (root.nodeType === 3) {
      translateTextNode(root);
      return;
    }
    if (root.nodeType !== 1 && root.nodeType !== 9 && root.nodeType !== 11) return;
    if (root.nodeType === 1 && excluded(root)) return;
    if (root.nodeType === 1) translateAttributes(root);
    // The initial HTML is always English. Code samples and user-provided
    // bibliographic data are never rewritten or sent to an external service.
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.nodeType === 3) translateTextNode(node);
      else if (!excluded(node)) translateAttributes(node);
    }
    const titleNow = document.title;
    if (titleNow !== titleLast) titleSource = titleNow;
    titleLast = translateString(titleSource);
    if (document.title !== titleLast) document.title = titleLast;
  }

  function schedule(root) {
    if (language === "en") return;
    if (root) pending.add(root);
    if (frameScheduled) return;
    frameScheduled = true;
    const flush = () => {
      frameScheduled = false;
      if (!document.body) return;
      if (pending.size > 40) pending.clear(), pending.add(document.body);
      for (const target of pending) {
        if (target.isConnected !== false) translate(target);
      }
      pending.clear();
    };
    if (typeof window.requestAnimationFrame === "function") {
      window.requestAnimationFrame(flush);
    } else setTimeout(flush, 0);
  }

  function updateMenu() {
    const menus = document.querySelectorAll("[data-language-menu]");
    for (const menu of menus) {
      for (const option of menu.querySelectorAll("[data-language-option]")) {
        option.setAttribute("aria-checked", String(option.dataset.languageOption === language));
      }
    }
  }

  function closeAllMenus() {
    for (const button of document.querySelectorAll("[data-language-toggle]")) {
      button.setAttribute("aria-expanded", "false");
    }
    for (const menu of document.querySelectorAll("[data-language-menu]")) menu.hidden = true;
  }

  function saveLanguage(next) {
    const valid = LANGUAGES.includes(next) ? next : null;
    if (!valid || valid === language) { closeAllMenus(); return; }
    try { localStorage.setItem(STORAGE_KEY, valid); } catch { /* cookie fallback */ }
    try {
      document.cookie = COOKIE_KEY + "=" + encodeURIComponent(valid)
        + "; Path=/; Max-Age=31536000; SameSite=Lax"
        + (window.location.protocol === "https:" ? "; Secure" : "");
    } catch { /* allow only-in-memory mode */ }
    // A full reload drops PJAX's cached translated DOM and reconstructs all
    // labels from canonical English. Keep the current path and search query.
    window.location.reload();
  }

  function mount() {
    translate(document.body);
    updateMenu();
    document.addEventListener("click", (event) => {
      const choice = event.target.closest("[data-language-option]");
      if (choice) { event.preventDefault(); saveLanguage(choice.dataset.languageOption); return; }
      const toggle = event.target.closest("[data-language-toggle]");
      if (toggle) {
        event.preventDefault();
        const menu = toggle.parentElement.querySelector("[data-language-menu]");
        if (!menu) return;
        const opening = menu.hidden;
        closeAllMenus();
        menu.hidden = !opening;
        toggle.setAttribute("aria-expanded", String(opening));
        if (opening) menu.querySelector('[aria-checked="true"]')?.focus();
        return;
      }
      if (!event.target.closest("[data-language-menu]")) closeAllMenus();
    });
    document.addEventListener("keydown", (event) => {
      const menu = event.target.closest("[data-language-menu]");
      if (event.key === "Escape") {
        if (menu && !menu.hidden) {
          event.preventDefault();
          const button = menu.parentElement.querySelector("[data-language-toggle]");
          closeAllMenus();
          button?.focus();
        }
      } else if (menu && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
        const options = [...menu.querySelectorAll("[data-language-option]")];
        const index = options.indexOf(document.activeElement);
        if (index !== -1) {
          event.preventDefault();
          options[(index + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length].focus();
        }
      }
    });
    if (language !== "en" && typeof MutationObserver === "function") {
      observer = new MutationObserver(records => {
        for (const record of records) {
          if (record.type === "childList") {
            record.addedNodes.forEach(node => pending.add(node));
          } else pending.add(record.target);
        }
        if (pending.size) schedule();
      });
      observer.observe(document.body, {
        childList: true, subtree: true, characterData: true,
        attributes: true, attributeFilter: ATTRIBUTES,
      });
    }
  }

  window.NetVaultI18n = Object.freeze({
    getLanguage: () => language,
    translate,
    translateString,
  });
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mount, {once: true});
  } else mount();
})();
